solutionCode:
import java.util.*;

public class Solution {
    static class Crivo {
        private final int[] spf;
        private final int[] acumulado;

        Crivo(int N) {
            spf = new int[N + 1];
            for (int p = 2; p <= N; p++) {
                if (spf[p] != 0) continue;
                spf[p] = p;
                for (long m = (long) p * p; m <= N; m += p) if (spf[(int) m] == 0) spf[(int) m] = p;
            }
            acumulado = new int[N + 1];
            for (int i = 2; i <= N; i++) acumulado[i] = acumulado[i - 1] + (spf[i] == i ? 1 : 0);
        }

        boolean primo(int x) { return x >= 2 && spf[x] == x; }

        int contarPrimosAte(int x) { return x < 2 ? 0 : acumulado[x]; }

        // O(log x): cada divisão pelo menor fator ao menos divide x por 2.
        List<Integer> fatorar(int x) {
            List<Integer> out = new ArrayList<>();
            while (x > 1) {
                out.add(spf[x]);
                x /= spf[x];
            }
            return out;
        }
    }
}

