import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void pequenos() {
        var c = new Solution.Crivo(100);
        assertTrue(c.primo(2));
        assertTrue(c.primo(97));
        assertFalse(c.primo(1));
        assertFalse(c.primo(91));
        assertEquals(25, c.contarPrimosAte(100));
        assertEquals(0, c.contarPrimosAte(1));
        assertEquals(List.of(2, 2, 3, 5), c.fatorar(60));
        assertEquals(List.of(), c.fatorar(1));
        assertEquals(List.of(97), c.fatorar(97));
    }

    @Test void dezMilhoes() {
        var c = new Solution.Crivo(10_000_000);
        assertEquals(664_579, c.contarPrimosAte(10_000_000));
        assertTrue(c.primo(9_999_991));
        assertEquals(List.of(2, 2, 2, 2, 2, 2, 2, 5, 5, 5, 5, 5, 5, 5), c.fatorar(10_000_000));
    }

    @Test void fatorPrimoGrande() {
        var c = new Solution.Crivo(10_000_000);
        assertEquals(List.of(3, 3_333_331), c.fatorar(9_999_993));
    }
}

