public class Solution {
    // mdc(a, b) = mdc(b, a % b): todo divisor comum de a e b divide a % b. O(log min).
    static long mdc(long a, long b) {
        while (b != 0) {
            long r = a % b;
            a = b;
            b = r;
        }
        return a;
    }

    static long mmc(long a, long b) { return a / mdc(a, b) * b; }

    static long encontro(long[] periodos) {
        long r = 1;
        for (long p : periodos) r = mmc(r, p);
        return r;
    }
}

